import argparse,json,sys
p=argparse.ArgumentParser()
p.add_argument("--input",required=True)
p.add_argument("--min-level",choices=["DEBUG","INFO","WARN","ERROR"],required=True)
a=p.parse_args()
rows=[json.loads(line) for line in open(a.input) if line.strip()]
if any(r["level"] not in ["DEBUG","INFO","WARN","ERROR"] for r in rows):
 print("unknown level",file=sys.stderr);sys.exit(2)
for row in rows:
 if row["level"]>=a.min_level:print(json.dumps(row))
